function unique(arr) {
  // return a Set of the distinct values
}

function union(a, b) {
  // return a Set of all values from both arrays
}

exercises.solution:
function union(a, b) {
  return new Set([...a, ...b])
}

exercises.starter:
function intersection(a, b) {
  // return a Set of the values found in both arrays
}

exercises.solution:
function intersection(a, b) {
  const setB = new Set(b)
  return new Set(a.filter(x => setB.has(x)))
}

exercises.starter:
function difference(a, b) {
  // return a Set of the values in a that are not in b
}

exercises.solution:
function difference(a, b) {
  const setB = new Set(b)
  return new Set(a.filter(x => !setB.has(x)))
}

exercises.starter:
function wordCounts(words) {
  // return a Map from each word to its count
}

exercises.solution:
function wordCounts(words) {
  const counts = new Map()
  for (const w of words) {
    counts.set(w, (counts.get(w) || 0) + 1)
  }
  return counts
}

exercises.starter:
function firstDuplicate(arr) {
  // return the first value seen twice, or null
}

exercises.solution:
function firstDuplicate(arr) {
  const seen = new Set()
  for (const x of arr) {
    if (seen.has(x)) return x
    seen.add(x)
  }
  return null
}
